for entity_name in Memo User Attachment Inbox MemoRelation MemoShare Reaction IdentityProvider UserSetting UserIdentity InstanceSetting; do
  case $entity_name in
    Memo)
      pattern='store\.\(Memo\b\|FindMemo\b\|UpdateMemo\b\|DeleteMemo\b\|FindMemoPayload\b\)' ;;
    User)
      pattern='store\.\(User\b\|FindUser\b\|UpdateUser\b\|DeleteUser\b\|DeleteUserResult\b\|ListUsers\b\)' ;;
    Attachment)
      pattern='store\.\(Attachment\b\|FindAttachment\b\|UpdateAttachment\b\|DeleteAttachment\b\)' ;;
    Inbox)
      pattern='store\.\(Inbox\b\|FindInbox\b\|UpdateInbox\b\|DeleteInbox\b\|InboxStatus\b\)' ;;
    MemoRelation)
      pattern='store\.\(MemoRelation\b\|FindMemoRelation\b\|DeleteMemoRelation\b\|MemoRelationType\b\|MemoRelationComment\b\|MemoRelationReference\b\)' ;;
    MemoShare)
      pattern='store\.\(MemoShare\b\|FindMemoShare\b\|DeleteMemoShare\b\)' ;;
    Reaction)
      pattern='store\.\(Reaction\b\|FindReaction\b\|DeleteReaction\b\)' ;;
    IdentityProvider)
      pattern='store\.\(IdentityProvider\b\|FindIdentityProvider\b\|UpdateIdentityProvider\|DeleteIdentityProvider\b\)' ;;
    UserSetting)
      pattern='store\.\(UserSetting\b\|FindUserSetting\b\|DeleteUserSetting\b\|RefreshTokenQueryResult\b\|PATQueryResult\b\)' ;;
    UserIdentity)
      pattern='store\.\(UserIdentity\b\|FindUserIdentity\b\|DeleteUserIdentity\b\)' ;;
    InstanceSetting)
      pattern='store\.\(InstanceSetting\b\|FindInstanceSetting\b\|DeleteInstanceSetting\b\)' ;;
  esac

  count=$(grep -rl "$pattern" --include="*.go" | grep -v "^store/" | grep -v "^proto/" | grep -v "_test.go" | sed 's|/[^/]*\.go$||' | sort -u | wc -l)
  echo "$count $entity_name"
done | sort -rn

